+    if (ageSec === null) {
+      freshnessEl.textContent = 'Freshness unknown';
+    } else if (ageSec < 60) {
+      freshnessEl.textContent = `Fresh – updated ${Math.round(ageSec)} seconds ago`;
+    } else {
