+  if (!tbody) return;
+  tbody.innerHTML = '';
+  const now = new Date();
+  const todayStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 0, 0, 0));
+  const intervalMs = INTERVAL_MINUTES * 60 * 1000;
