+    const tdUtc = document.createElement('td');
+    tdUtc.textContent = formatUTC(wake);
+    tr.appendChild(tdNum);
+    tr.appendChild(tdLocal);
+    tr.appendChild(tdUtc);
+    tbody.appendChild(tr);
+  }
