+        list.appendChild(li);
+      });
+    })
+    .catch(e => {
+      console.error('Failed to load recent tweaks:', e);
+      list.innerHTML = '<li>Unable to load recent tweaks</li>';
+    });
+}
+
+function announceCopy(msgEl, regionEl) {
+  if (!regionEl) return;
+  regionEl.textContent = msgEl.textContent;
+  regionEl.focus();
+  regionEl.select();
+  try {
